window.REPORT_PRELOAD_CACHE["EDU.html"] = {"version":"6b992a11809f3d2f33de12c0a33f32586d17cfb0a8744523e2053d88c68a45d6","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>新东方教育科技集团 New Oriental Education (NYSE: EDU / HKEX: 9901) 深度研究报告：从双减重塑转型到素质教育、出国考试与东方甄选全生态复利引擎</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n edured: {\n 400: '#FF6B6B',\n 500: '#003366',\n 600: '#002244',\n accent: '#D9381E',\n },\n accent: {\n 500: '#3B82F6',\n 600: '#2563EB',\n },\n teal: {\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(0, 51, 102, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n border-left: 3px solid #003366;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-blue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-blue-600 via-emerald-400 to-teal-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center font-extrabold text-white shadow\">\n 新\n </div>\n <div>\n <div class=\"text-[11px] text-blue-400 font-semibold tracking-wider uppercase\">NYSE: EDU / HKEX: 9901 · Equity Research</div>\n <div class=\"text-sm font-bold leading-tight\">新东方 New Oriental 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">EDU 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球教育与消费文旅研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (FY26 / Q1 FY27)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <!-- 机构品牌头 -->\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-blue-500/25\">\n 新\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-blue-400 bg-blue-500/15 px-2 py-0.5 rounded\">NYSE: EDU / HK: 9901</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">新东方深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球私立教育服务龙头 · 素质教育、出国考试与东方甄选全生态复利引擎\n </p>\n </div>\n\n <!-- 股票实时快照徽章 -->\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">当前 ADR 股价</span>\n <span class=\"font-mono font-bold text-white\">$53.28 <span class=\"text-emerald-400\">(+1.45%)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">FY2026 全年营收</span>\n <span class=\"font-mono font-bold text-teal-400\">$5.66B <span class=\"text-slate-400\">(+15.5%)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">分析师平均目标价</span>\n <span class=\"font-mono font-bold text-blue-400\">~$70.57 (32.4% 潜在上涨空间)</span>\n </div>\n </div>\n\n <!-- 六个核心章节目录导航 -->\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-blue-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <!-- 侧边栏底部工具栏 -->\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-blue-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-xs font-extrabold transition shadow-sm\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <!-- 顶部研报元数据标签栏 -->\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-blue-500/15 text-blue-600 dark:text-blue-400 font-bold border border-blue-500/30\">评级：买入 / 核心素质教育与文旅复苏标的</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：FY2026–FY2027 素质教育高速扩张与东方甄选协同期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NYSE: EDU / HK: 9901</span>\n </div>\n </div>\n\n <!-- Hero 标题卡片 -->\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#3B82F6 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-blue-500/20 border border-blue-500/40 text-blue-400 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-blue-400 animate-pulse\"></span>\n <span>CORE THESIS · “双减”后涅槃重生 × FY26 营收 $5.66B（+15.5%）与核心素质教育、出国考试双轮驱动</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 新东方教育科技集团 New Oriental Education & Technology Group Inc. (NYSE: EDU / HKEX: 9901) 深度研究报告：从双减重塑转型到素质教育、出国考试与东方甄选全生态复利引擎\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 新东方已成功完成从传统K-12学科培训向<strong class=\"text-white\">全方位素质教育、出国留学考试、成人培训及文旅直播电商（东方甄选）</strong>的全面华丽转身。FY2026 全年总营收达到 <strong class=\"text-blue-400\">$5.66B (+15.5% YoY)</strong>，净利润达 $4.75 亿（+27.8% YoY）。\n 伴随 Q1 FY2027 营收继续实现 23.1% 的高速增长并超越指引上限，公司在持续推进成本控制与股东回报（回购/分红）的同时，正以极具吸引力的估值享受高质量复利增长。\n </p>\n\n <!-- 核心投资结论高亮条 -->\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">强劲财务复苏与利润扩张</div>\n <div class=\"text-white font-semibold\">FY26 营收达 $5.66B（+15.5%），净利润大增 27.8% 至 $4.75B，毛利与运营效率双升</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">素质教育与留学双引擎爆发</div>\n <div class=\"text-blue-400 font-semibold\">非学科类素质教育网点与出国咨询业务保持高景气，Q1 FY27 营收增速达 23.1%</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">华尔街一致强烈推荐</div>\n <div class=\"text-teal-400 font-semibold\">分析师平均目标价 $70.57，潜在上涨空间超 32%，高盛与美银等机构集体上调评级</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <!-- KPI 1 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>FY2026 全年总营收</span>\n <span class=\"p-1.5 rounded-lg bg-blue-500/15 text-blue-600 dark:text-blue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$5.66B</span>\n <span class=\"text-xs font-bold text-blue-600 dark:text-blue-400 bg-blue-500/15 px-2 py-0.5 rounded\">+15.5% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 素质教育、出国留学咨询及文旅新业务多点开花，推动千亿规模体量下维持高双位数增长。\n </p>\n </div>\n\n <!-- KPI 2 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>FY2026 全年净利润</span>\n <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$475M</span>\n <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">+27.8% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 运营杠杆释放与严格的成本费用控制，推动利润增速显著快于营收增速，盈利质量大幅优化。\n </p>\n </div>\n\n <!-- KPI 3 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q1 FY2027 季度表现</span>\n <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">+23.1%</span>\n <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">超越指引上限</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 最新季度营收同比强劲增长 23.1%，核心教育与东方甄选、文旅新业务协同发力，成长势能依旧。\n </p>\n </div>\n\n <!-- KPI 4 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>华尔街目标价 & 共识</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$70.57</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">买入共识</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 高盛、美银、汇丰等主流投行一致给予“买入”评级，平均目标价指向 $70.57，具备高性价比。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 业务与收入架构 (Business & Revenue Architecture)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-blue-600 dark:text-blue-400\">Section 01 · Business & Revenue Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：素质教育、出国考试与“东方甄选”文旅新生态</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY2026 总营收 $5.66B · 多元化业务矩阵协同</span>\n </div>\n\n <!-- 交互式 Chart.js 双视图切换面板 -->\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <!-- 左侧：双视图图表 -->\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2022–FY2027E 集团营收演进与业务板块扩张</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">核心教育业务强劲反弹，东方甄选与文旅新业务贡献第二增长曲线</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-blue-600 dark:text-blue-400 shadow-sm transition\">视图A：年度营收演进</button>\n <button onclick=\"switchBizChart('segments')\" id=\"btn-chart-seg\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：核心业务板块占比</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <!-- 右侧：结构性拆解核心洞察 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性支柱</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-blue-500/15 text-blue-600 dark:text-blue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">出国考试准备与出国咨询业务</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 作为新东方立业之本，托福、雅思、GRE 等出国考试培训及海外留学咨询在后疫情时代迎来全面复苏，客单价与学员人数持续双升。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">非学科类素质教育与成人培训</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 顺应政策导向推出的素质教育（编程、机器人、美术、科学等）及大学生/成人考试培训网点已在全国数百个城市成熟铺开，成为K-12转型后的全新基本盘。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">东方甄选直播电商与文旅新业务</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 东方甄选（East Buy）在农产品电商与私域直播保持领先，同时切入文化旅游市场（文旅直播与精品游），构筑起独特的“教育+科技+文旅”商业生态。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">核心增长驱动力</span>\n <span class=\"font-bold text-blue-600 dark:text-blue-400\">素质教育扩容 + 东方甄选矩阵放量</span>\n </div>\n </div>\n </div>\n\n <!-- 核心业务板块矩阵卡片 -->\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-blue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-blue-500/15 text-blue-600 dark:text-blue-400 text-xs font-bold\">基本盘 · 出国考试与咨询</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">海外留学高景气</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">出国考试与留学咨询</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 覆盖全年龄段出国留学备考、背景提升及海外游学。伴随全球留学需求反弹，高端咨询业务客单价与毛利率表现优异。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n 行业绝对龙头 · 品牌壁垒深厚\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">成长引擎 · 素质教育</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">网点快速扩张</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">素质教育与K-9非学科培训</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 专注于培养学生综合素养与创新能力的非学科类课程（编程、机器人、美育等），在全国各大一二线城市网点实现强劲盈利。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n 产能利用率提升 · 规模效应显现\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">新生态 · 东方甄选与文旅</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">直播电商+文化旅游</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">东方甄选与文旅新业务</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 东方甄选直播电商矩阵持续孵化农产品与自有品牌爆款；同时进军文旅市场，打造具有文化底蕴的特色旅游产品，创造全新增量。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold\">\n 独特的跨界商业模式 · 强曝光变现\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与四重核心护城河 (Industry Position & Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：品牌信任、师资沉淀与全生态网络</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat · 中国私立教育金字招牌)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <!-- 左侧：四重护城河深度解析 -->\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-blue-500/15 text-blue-600 dark:text-blue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">三十年积累的国民级品牌信任资产</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n “新东方”三字在中国数代学生及家长心中享有极高的美誉度与正向品牌心智。在经历行业剧烈变革后，这种信任资产反而转化为更强的家长粘性。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">卓越的优质师资保留与教研体系</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 拥有业内顶尖的教师培训、薪酬激励与教研开发机制。即便在转型期也能稳住核心教学骨干，确保各网点课程质量始终处于行业金字塔尖。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全国一二线城市线下网点矩阵</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 经过多年的网点优化与重新布局，新东方在全国核心城市拥有高效的线下学习中心网络，形成“线上赋能+线下深度服务”的OMO运营闭环。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">独特的“教育+电商+文旅”跨界协同生态</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 东方甄选的巨大全网曝光与文化调性为新东方品牌持续注入年轻客群，同时反哺文旅及素质教育业务，形成独特的互补生态圈。\n </p>\n </div>\n </div>\n\n <!-- 右侧：五维护城河雷达图 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">私立教育与文化服务五维护城河量化雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">新东方 (EDU) vs 传统教培同行 vs 在线教育纯平台（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 同行竞争格局横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-blue-600 dark:text-blue-400\">Section 03 · Global Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：素质教育领头羊 vs 垂直教育机构</h2>\n </div>\n <!-- 交互式筛选按钮 -->\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-blue-600 text-white shadow-sm transition\">全部阵营</button>\n <button onclick=\"filterCompetitors('education')\" data-filter=\"education\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">综合私立教育集团</button>\n <button onclick=\"filterCompetitors('online')\" data-filter=\"online\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">在线与垂直教育同行</button>\n </div>\n </div>\n\n <!-- 横向对比矩阵表格 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心平台</th>\n <th class=\"py-4 px-4 min-w-[130px]\">主营业务与核心定位</th>\n <th class=\"py-4 px-4 min-w-[140px]\">市值/体量特征</th>\n <th class=\"py-4 px-4 min-w-[135px]\">毛利率与盈利质量</th>\n <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞争评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"education\" class=\"bg-blue-500/5 dark:bg-blue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-blue-600 text-white text-[10px] font-extrabold\">行业龙头</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">新东方 New Oriental (EDU)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">素质教育、出国考试、东方甄选</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">全品类私立教育与文旅电商生态</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">市值 ~$8.3B · 营收 $5.66B</td>\n <td class=\"py-4 px-4 font-mono font-bold text-blue-600 dark:text-blue-400\">毛利稳健，净利大增 27.8%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>涅槃重生与生态协同：</strong>双减后转型最成功的教育巨头，兼具教育稳健增长与直播电商新流量。\n </td>\n </tr>\n\n <tr data-category=\"education\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">好未来 TAL Education (TAL)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">老牌K-12与素质教育转型者</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">素质教育、学习机硬件与国际教育</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">中概教育股重要标的</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">逐步恢复盈利</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>教研与科技驱动：</strong>在小班面授素质教育及学习机智能硬件上具备极强技术积累，与新东方形成双雄并立。\n </td>\n </tr>\n\n <tr data-category=\"online\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">高途 Gaotu Techedu (GOTU)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">在线成人与素质教育平台</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">成人教育、考研及在线辅导</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">垂直在线教育公司</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">波动性相对较大</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>纯在线灵活性高：</strong>专注于线上成人教育与考研培训，但线下服务网络及品牌矩阵厚度较新东方有一定差距。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <!-- 配套 Chart.js 横向条形图：营收与增速对比 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">主要中概教育集团年度营收规模对比（单位：亿美元）</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">新东方凭借 $5.66 亿（FY26）的全年营收规模稳居行业绝对领头羊地位</p>\n </div>\n <span class=\"text-xs font-semibold text-blue-600 dark:text-blue-400 bg-blue-500/15 px-2.5 py-1 rounded\">规模效应带来卓越抗风险能力</span>\n </div>\n <div class=\"relative h-60 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：营收破 $5.6B 与 32% 潜在上涨空间</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">动态 P/E ~16.7x · 分析师目标价 $70.57</span>\n </div>\n\n <!-- 1. 财务健康度四大硬核指标卡 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-blue-600 dark:text-blue-400 uppercase\">Revenue Growth (TTM)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">+20.6%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 最新 TTM 营收增速保持在 20.6% 的高景气区间，教育主业与新业务双引擎全速运转。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Net Income Growth</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">+38.3%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 净利润表现远超营收增速，运营效率提升与成本精简带来爆发式的盈利红利。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Operating Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~11.8%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 营业利润率位居行业前列，网点产能利用率爬坡带动利润率持续向上扩张。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Valuation P/E</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~16.7x</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 动态市盈率约为 16.7x，结合 20%+ 的成长增速，PEG 显著低于 1，具备极高投资性价比。\n </p>\n </div>\n </div>\n\n <!-- 2. 交互式 Chart.js 财务演进双轴图 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2022–FY2027E 营收与净利润（Earnings）复苏演进趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">双减阵痛期后业绩强势V型反转：FY26 营收达 $5.66B，净利润突破 $4.75 亿</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-blue-600 dark:text-blue-400 bg-blue-500/10 px-2.5 py-1 rounded\">平均目标价 $70.57</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <!-- 3. 互动式复利推演计算器 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col md:flex-row justify-between md:items-center gap-4 mb-6\">\n <div>\n <h3 class=\"text-lg font-bold text-white\">新东方 (EDU) 投资回报与复利推演器</h3>\n <p class=\"text-xs text-slate-400 mt-1\">模拟在不同营收增速与估值修复预期下的长期持仓市值与复合回报率</p>\n </div>\n <span class=\"text-xs px-3 py-1 rounded-full bg-slate-800 text-blue-300 border border-slate-700\">交互式推演模型</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-8 items-center\">\n <div class=\"space-y-5\">\n <div>\n <div class=\"flex justify-between text-sm mb-1\">\n <span class=\"text-slate-300\">初始投资本金 (USD)</span>\n <span id=\"invVal\" class=\"font-bold text-white\">$20,000</span>\n </div>\n <input id=\"invSlider\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"20000\" class=\"w-full accent-blue-500 cursor-pointer\">\n </div>\n <div>\n <div class=\"flex justify-between text-sm mb-1\">\n <span class=\"text-slate-300\">持有年限 (Years)</span>\n <span id=\"yrVal\" class=\"font-bold text-white\">3 年</span>\n </div>\n <input id=\"yrSlider\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"3\" class=\"w-full accent-blue-500 cursor-pointer\">\n </div>\n <div>\n <div class=\"flex justify-between text-sm mb-1\">\n <span class=\"text-slate-300\">预期年化营收/盈利增速</span>\n <span id=\"grVal\" class=\"font-bold text-blue-400\">15.0%</span>\n </div>\n <input id=\"grSlider\" type=\"range\" min=\"5\" max=\"25\" step=\"0.5\" value=\"15.0\" class=\"w-full accent-blue-500 cursor-pointer\">\n </div>\n </div>\n\n <div class=\"lg:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4\">\n <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n <div class=\"text-xs text-slate-400\">期末预计总资产市值</div>\n <div id=\"finalBalance\" class=\"text-2xl font-bold text-white mt-2\">$30,452</div>\n <div id=\"totalGainPct\" class=\"text-xs text-blue-400 mt-1\">累计总回报 +52.3%</div>\n </div>\n <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n <div class=\"text-xs text-slate-400\">期末对应隐含股价</div>\n <div id=\"impliedPrice\" class=\"text-2xl font-bold text-teal-400 mt-2\">$81.10</div>\n <div class=\"text-xs text-slate-400 mt-1\">向华尔街目标价 ($70.57+) 迈进</div>\n </div>\n <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n <div class=\"text-xs text-slate-400\">隐含复合年化回报 (CAGR)</div>\n <div id=\"cagrVal\" class=\"text-2xl font-bold text-amber-400 mt-2\">15.0%</div>\n <div class=\"text-xs text-slate-400 mt-1\">素质教育与文旅高速成长驱动</div>\n </div>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-blue-600 dark:text-blue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与核心风险评估</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：中概成长与教育消费组合的核心标的</span>\n </div>\n\n <!-- 1. 三情景估值推演卡片 -->\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-blue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-blue-500/15 text-blue-600 dark:text-blue-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-blue-600 dark:text-blue-400\">概率：30%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标价格：$75.00 – $85.00</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>素质教育与出国考试需求持续超出预期（保持 20%+ 增长），东方甄选文旅电商贡献超预期增量利润，估值向 22x P/E 靠拢。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-blue-600 dark:text-blue-400\">\n 潜在上行空间：+40% 至 +60%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标价格：$68.00 – $73.00</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>FY27 营收顺利达成 14%–18% 增长指引，利润率温和扩张，投资者稳步兑现华尔街平均目标价 $70.57。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n 潜在上行空间：+25% 至 +35%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防御底线：$42.00 – $46.00</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宏观消费意愿放缓导致教育与培训需求增长斜率放缓，东方甄选电商业务利润波动，估值倍数阶段性回调。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在下行回撤：-10% 至 -15% (受良好现金流支撑)\n </div>\n </div>\n </div>\n\n <!-- 2. 四大核心风险评估矩阵 -->\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构应对策略</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 教育行业政策监管调整风险</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">非学科培训与素质教育政策变动</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管素质教育符合国家鼓励方向，但教育行业的政策敏感度历来较高，任何关于非学科培训收费、网点合规的边际变化都需持续关注。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 海外留学与地缘政治摩擦风险</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">出国留学签证与国际关系波动</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 出国考试与留学咨询业务深度依赖主要留学目的地国（美、英、澳等）的签证政策及国际双边关系，地缘政治摩擦可能影响留学意愿。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 东方甄选直播电商舆情与波动</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">直播电商行业竞争与主播/选品风险</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 东方甄选作为上市公司的重要联营/子公司，直播电商业务面临极高的行业竞争与涉网舆情风险，可能对短期投资收益造成波动。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 线下网点扩张成本与产能爬坡</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：低中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">新开学习中心前期固定成本压力</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 随着素质教育网点在全国持续拓展，若新开中心招生人数爬坡速度不及预期，可能在短期内对各分校的经营利润率造成微幅摊薄。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-blue-500/15 text-blue-600 dark:text-blue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选机构财报追踪已验证达标的核心指标（状态自动本地保存），用高频基本面事实动态校准投资逻辑：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <!-- KPI 1 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-blue-600 focus:ring-blue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 全年营收增速是否稳守 14%–18% 业绩指引区间</span>\n <span class=\"text-[11px] font-mono text-blue-600 dark:text-blue-400 font-semibold shrink-0\">成长速度锚点</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪每季财报公布的营收同比增速（如 Q1 实际达 23.1%），确保全年 14%–18% 增长目标顺利达成。\n </p>\n </div>\n </label>\n\n <!-- KPI 2 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-blue-600 focus:ring-blue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 非学科类素质教育与出国咨询业务的学员人数扩张</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">核心主业动能</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控各大核心城市学习中心的报名人数、续报率及线下网点产能利用率爬坡进度。\n </p>\n </div>\n </label>\n\n <!-- KPI 3 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-blue-600 focus:ring-blue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 营业利润率与经营效率持续优化（Cost Control）</span>\n <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">利润率扩张指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 评估新东方在扩张网点的同时，管理费用率与销售费用率的管控成效，确保净利润增速跑赢营收。\n </p>\n </div>\n </label>\n\n <!-- KPI 4 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-blue-600 focus:ring-blue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 东方甄选（East Buy）与文旅新业务的贡献与协同</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">第二曲线验证</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 追踪东方甄选 GMV、自营产品矩阵渗透率及精品文旅线路的营收利润贡献。\n </p>\n </div>\n </label>\n\n <!-- KPI 5 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-blue-600 focus:ring-blue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 线下学习中心网点净新增数量与地理布局</span>\n <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">线下扩张速度</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 统计每季末学习中心总数及平方英尺容量变化，评估新网点开设计划的执行力度。\n </p>\n </div>\n </label>\n\n <!-- KPI 6 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-blue-600 focus:ring-blue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 股东资本回报计划（股份回购与现金分红执行）</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">股东价值回馈</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监督公司管理层关于利用充沛现金流开展股份回购及回报股东的实际资金额度与节奏。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 页脚免责声明 (Disclaimer Footer)\n ========================================================= -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>新东方教育科技集团 New Oriental Education (NYSE: EDU / HKEX: 9901) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：FY2026 年报及 2026 年 11 月最新市场一致预期</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：**本深度研究报告基于公司公开财务报告、SEC 20-F 文件及市场公开一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的财务预测、三情景估值模型及推演数据均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n </p>\n </footer>\n\n </div>\n </main>\n\n <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-blue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-blue-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-blue-600', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-blue-600', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n const KPI_STORAGE_KEY = 'edu_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const revConfig = {\n type: 'bar',\n data: {\n labels: ['FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026', 'FY2027E'],\n datasets: [\n {\n label: '素质教育与出国考试核心教育 ($B)',\n data: [2.5, 3.0, 3.9, 4.3, 4.8, 5.5],\n backgroundColor: '#003366',\n borderRadius: 4,\n },\n {\n label: '东方甄选与文旅新业务 ($B)',\n data: [0.5, 0.8, 0.9, 0.6, 0.86, 1.0],\n backgroundColor: '#3B82F6',\n borderRadius: 4,\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n }\n }\n },\n scales: {\n x: {\n stacked: true,\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n stacked: true,\n max: 7.5,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n const segConfig = {\n type: 'bar',\n data: {\n labels: [\n '出国考试准备与咨询',\n '非学科素质教育',\n '成人与大学生培训',\n '东方甄选与文旅电商'\n ],\n datasets: [\n {\n label: '营收贡献比例 (%)',\n data: [42, 35, 10, 13],\n backgroundColor: [\n '#003366',\n '#06B6D4',\n '#3B82F6',\n '#D9381E'\n ],\n borderRadius: 6,\n barThickness: 28\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `营收占比: ${ctx.parsed.y}%`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n max: 50,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue' ? revConfig : segConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnSeg = document.getElementById('btn-chart-seg');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-blue-600 dark:text-blue-400 shadow-sm transition';\n btnSeg.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n titleEl.textContent = 'FY2022–FY2027E 集团营收演进与业务板块扩张';\n subEl.textContent = '核心教育业务强劲反弹，东方甄选与文旅新业务贡献第二增长曲线';\n } else {\n btnSeg.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-blue-600 dark:text-blue-400 shadow-sm transition';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n titleEl.textContent = '核心业务板块营收贡献占比分布';\n subEl.textContent = '出国考试与非学科素质教育构成双核压舱石';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '国民级品牌信任与美誉度',\n '优质师资保留与教研体系',\n '全国线下学习中心矩阵(OMO)',\n '教育+电商+文旅跨界生态',\n '合规运营与抗政策风险能力'\n ],\n datasets: [\n {\n label: '新东方 New Oriental (EDU)',\n data: [9.8, 9.5, 9.4, 9.6, 9.2],\n borderColor: '#003366',\n backgroundColor: 'rgba(0, 51, 102, 0.22)',\n pointBackgroundColor: '#003366',\n borderWidth: 2.5\n },\n {\n label: '传统教培同行平均',\n data: [7.5, 7.2, 7.0, 5.0, 7.5],\n borderColor: '#3B82F6',\n backgroundColor: 'rgba(59, 130, 246, 0.14)',\n pointBackgroundColor: '#3B82F6',\n borderWidth: 1.8\n },\n {\n label: '在线教育纯平台',\n data: [6.0, 5.5, 3.5, 4.0, 6.0],\n borderColor: '#94A3B8',\n backgroundColor: 'rgba(148, 163, 184, 0.12)',\n pointBackgroundColor: '#94A3B8',\n borderWidth: 1.5,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n '新东方 New Oriental (EDU · FY26)',\n '好未来 TAL Education',\n '高途集团 GOTU'\n ],\n datasets: [{\n label: '全年营业收入 ($B)',\n data: [5.66, 2.10, 0.48],\n backgroundColor: [\n '#003366',\n '#3B82F6',\n '#06B6D4'\n ],\n borderRadius: 6,\n barThickness: 28\n }]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `营收规模: $${ctx.parsed.x}B`\n }\n }\n },\n scales: {\n x: {\n max: 7.0,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2022', '2023', '2024', '2025', '2026'],\n datasets: [\n {\n type: 'bar',\n label: '全年总营收 ($B)',\n data: [3.10, 3.00, 4.31, 4.90, 5.66],\n backgroundColor: 'rgba(0, 51, 102, 0.85)',\n borderRadius: 5,\n barThickness: 26,\n yAxisID: 'y'\n },\n {\n type: 'bar',\n label: '净利润 Earnings ($M)',\n data: [180, 260, 310, 371, 475],\n backgroundColor: 'rgba(16, 185, 129, 0.85)',\n borderRadius: 5,\n barThickness: 26,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => ctx.dataset.yAxisID === 'y'\n ? `${ctx.dataset.label}: $${ctx.parsed.y}B`\n : `${ctx.dataset.label}: $${ctx.parsed.y}M`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n max: 7.0,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 600,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v + 'M' }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n // Calculator Logic\n const invSlider = document.getElementById('invSlider');\n const yrSlider = document.getElementById('yrSlider');\n const grSlider = document.getElementById('grSlider');\n\n function updateCalculator() {\n const principal = parseFloat(invSlider.value);\n const years = parseInt(yrSlider.value);\n const growthRate = parseFloat(grSlider.value) / 100;\n\n document.getElementById('invVal').textContent = '$' + principal.toLocaleString();\n document.getElementById('yrVal').textContent = years + ' 年';\n document.getElementById('grVal').textContent = (growthRate * 100).toFixed(1) + '%';\n\n const finalVal = principal * Math.pow(1 + growthRate, years);\n const totalGain = finalVal - principal;\n const gainPct = (totalGain / principal) * 100;\n const impliedPrice = 53.28 * Math.pow(1 + growthRate * 0.85, years);\n\n document.getElementById('finalBalance').textContent = '$' + Math.round(finalVal).toLocaleString();\n document.getElementById('totalGainPct').textContent = '累计总回报 +' + gainPct.toFixed(1) + '%';\n document.getElementById('impliedPrice').textContent = '$' + impliedPrice.toFixed(2);\n document.getElementById('cagrVal').textContent = (growthRate * 100).toFixed(1) + '%';\n }\n\n [invSlider, yrSlider, grSlider].forEach(el => el.addEventListener('input', updateCalculator));\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n updateCalculator();\n });\n </script>\n</body>\n</html>\n"};
